// ─── File: RedisInternalsDemo.java ───
// Models why Redis is fast: in-memory + single-threaded serial execution
// (no locks, no context switch) + Redis 6.0 parallel I/O parsing.
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class RedisInternalsDemo {
    private static final Logger log = Logger.getLogger("REDISINT");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        InMemoryStore store = new InMemoryStore();
        store.set("balance:SAV2001", "1000000");

        // Redis 6.0: I/O threads PARSE many client requests in parallel.
        IoThreadPool io = new IoThreadPool(4);
        List<String> rawRequests = List.of(
            "GET balance:SAV2001", "INCR ratelimit:SAV2001", "INCR ratelimit:SAV2001", "GET balance:SAV2001");
        List<Command> parsed = io.parseAll(rawRequests);   // parallel parsing
        io.shutdown();

        // Single main thread EXECUTES commands one at a time (lock-free, atomic).
        EventLoop loop = new EventLoop(store);
        log.info("=== Serial execution on ONE thread (no locks, atomic) ===");
        for (Command c : parsed) {
            String result = loop.execute(c);
            log.info(() -> c.raw() + " => " + result);
        }

        // A SLOW command blocks the single thread and stalls everyone.
        log.info("=== Slow command (e.g. KEYS over millions) blocks the loop ===");
        long start = System.currentTimeMillis();
        loop.execute(new Command("SLOWSCAN *", 60));   // simulated 60ms stall
        log.warning(() -> "SLOWSCAN blocked the single thread for "
                + (System.currentTimeMillis() - start) + "ms — all other clients waited");
    }
}

// ─── store/InMemoryStore.java (all data in RAM; no disk on hot path) ───
class InMemoryStore {
    private final Map<String, String> data = new HashMap<>();  // no concurrent map needed:
    String get(String k) { return data.getOrDefault(k, "(nil)"); }       // only ONE thread touches it
    String set(String k, String v) { data.put(k, v); return "OK"; }
    String incr(String k) {
        long v = Long.parseLong(data.getOrDefault(k, "0")) + 1;  // atomic by serialization, no lock
        data.put(k, Long.toString(v));
        return Long.toString(v);
    }
}

// ─── command/Command.java ───
class Command {
    private final String raw; private final int slowMs;
    Command(String raw) { this(raw, 0); }
    Command(String raw, int slowMs) { this.raw = raw; this.slowMs = slowMs; }
    String raw() { return raw; } int slowMs() { return slowMs; }
}

// ─── loop/EventLoop.java (single-threaded serial executor) ───
class EventLoop {
    private final InMemoryStore store;
    EventLoop(InMemoryStore store) { this.store = store; }
    // Executes ONE command fully before the next — atomicity for free, no locks.
    String execute(Command c) {
        if (c.slowMs() > 0) { try { Thread.sleep(c.slowMs()); } catch (InterruptedException ignored) {} }
        String[] parts = c.raw().split(" ");
        switch (parts[0]) {
            case "GET":  return store.get(parts[1]);
            case "SET":  return store.set(parts[1], parts[2]);
            case "INCR": return store.incr(parts[1]);
            default:     return "(slow/other)";
        }
    }
}

// ─── io/IoThreadPool.java (Redis 6.0: parallel read/write/parse only) ───
class IoThreadPool {
    private final ExecutorService pool;
    IoThreadPool(int threads) { pool = Executors.newFixedThreadPool(threads); }
    // Parse raw socket bytes into Command objects in PARALLEL (network work only).
    List<Command> parseAll(List<String> raws) throws Exception {
        List<Future<Command>> futures = new ArrayList<>();
        for (String raw : raws) futures.add(pool.submit(() -> new Command(raw)));
        List<Command> out = new ArrayList<>();
        for (Future<Command> f : futures) out.add(f.get());
        return out;   // execution of these still happens serially on the main thread
    }
    void shutdown() { pool.shutdown(); }
}

// ─── config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
